// AllCDNDedicateds iterates over every object ListCDNDedicateds lists, fetching each one with
// GetCDNDedicated only when the loop reaches it. An object deleted in the meantime is skipped; on
// any other error it yields the error and stops.
func (s *Service) AllCDNDedicateds(ctx context.Context) iter.Seq2[[]string, error] {
	return ovh.Each(ctx,
		func(ctx context.Context) ([]string, error) {
			return s.ListCDNDedicateds(ctx)
		},
		func(ctx context.Context, listedID string) ([]string, error) {
			return s.GetCDNDedicated(ctx, listedID)
		})
}

